import itertools, json

# literals: l1,l2,l3, a, b (positive or negative). Represent as strings like 'l1','~l1', etc.
vars = ['l1','l2','l3','a','b']
lit_options = []
for v in vars:
    lit_options.append(v)
    lit_options.append('~'+v)

# generate clause as 3 distinct vars (by absolute variable) with signs.
def gen_clauses():
    for combo in itertools.combinations(vars,3):
        for signs in itertools.product([1,-1], repeat=3):
            clause = []
            for v, s in zip(combo, signs):
                clause.append(v if s==1 else '~'+v)
            yield tuple(clause)

clauses_list = list(gen_clauses())

# evaluate NAE clause under assignment dict of bools for each var.
def eval_clause(clause, assign):
    vals = []
    for lit in clause:
        if lit.startswith('~'):
            var = lit[1:]
            val = not assign[var]
        else:
            var = lit
            val = assign[var]
        vals.append(val)
    # NAE satisfied if not all equal
    return not (all(vals) or not any(vals))

# check gadget: list of clauses, for each assignment to l1,l2,l3 there exists assignment to a,b making all clauses true.

def gadget_ok(gclauses):
    for lvals in itertools.product([False,True], repeat=3):
        assign_fixed = {'l1':lvals[0],'l2':lvals[1],'l3':lvals[2]}
        exists=False
        for a_val in [False,True]:
            for b_val in [False,True]:
                assign = dict(assign_fixed)
                assign['a']=a_val
                assign['b']=b_val
                if all(eval_clause(c, assign) for c in gclauses):
                    exists=True
                    break
            if exists:
                break
        # condition: exists iff at least one of l1,l2,l3 true
        should = any(lvals)
        if exists != should:
            return False
    return True

# search for small gadgets up to 3 clauses
for r in range(1,4):
    for combo in itertools.combinations(clauses_list, r):
        if gadget_ok(combo):
            print('Found gadget with', r, 'clauses:', combo)
            raise SystemExit
print('none found')
